  function getBlogList() {
    return new Promise((resolve, rejuct) => {
      const temBlogList = uni.getStorageSync("temBlogList");
      if (temBlogList) {
        resolve(temBlogList);
        return;
      }
      uni.showLoading({
        title: "正在请求网络..."
      });
      uni.request({
        url: ""
      }).then((res) => {
        formatAppLog("log", "at utils/tools.js:16", "网络请求获取到数据...", res);
        resolve(res);
      }).catch((err) => {
        formatAppLog("log", "at utils/tools.js:19", err.message);
        rejuct(err);
        uni.showToast({
          title: "网络请求错误!",
          icon: "error"
        });
      }).finally(() => {
        setTimeout(() => {
          uni.hideLoading();
          uni.hideToast();
        }, 2e3);
      });
    });
  }
  function getCityByIP(ip) {
    return new Promise((resolve, reject) => {
      const storange_city = uni.getStorageSync(ip);
      if (storange_city) {
        const { name, time } = storange_city;
        const diff_time = Date.now() - time;
        if (diff_time > 0 && diff_time < 1e3 * 60 * 60 * 2) {
          resolve(name);
          return;
        }
        uni.removeStorageSync(ip);
      }
      uni.request({
        url: "https://restapi.amap.com/v3/ip?key=5271bffc983efad7f332841436f495bb&ip=" + ip
      }).then((res) => {
        const { province, city } = res.data;
        const obj = {
          name: province + city,
          time: Date.now()
        };
        if (obj.name == null || obj.name == "") {
          obj.name = "火星";
        }
        uni.setStorageSync(ip, obj);
        resolve(obj.name);
      }).catch((err) => {
        reject(err);
      });
    });
  }
  async function getCity() {
    const res = await uni.request({
      url: "https://restapi.amap.com/v3/ip?key=5271bffc983efad7f332841436f495bb"
    });
    let pc = "火星";
    const { province, city } = res.data;
    if (province || city) {
      pc = province + city;
    }
    return pc;
  }
